        source=base/('source-intake-1/1.6.2/source' if version=='1.6.2' else 'source-recovery-1/1.3.0/source');original=folder/'original';original.mkdir();command=['C:/Program Files/R/R-4.6.1/bin/Rscript.exe','--vanilla',str(script),str(original),str(source),version,*map(str,libraries)];save(folder/'STARTED.json',dict(source_pins=pins,artifact=build['artifact'],command=command,libraries=list(map(str,libraries))));r=subprocess.run(command,cwd=ROOT,env=dict(os.environ,LANG='C',LC_ALL='C',LANGUAGE='en',R_LIBS=';'.join(map(str,libraries)),OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1'),stdin=subprocess.DEVNULL,capture_output=True,timeout=60);(original/'stdout').write_bytes(r.stdout);(original/'stderr').write_bytes(r.stderr);save(original/'process.json',dict(command=command,exit_code=r.returncode));assert r.returncode==0;reference=json.loads((original/'controls.json').read_bytes());assert reference['source_bodies_and_formals_checked_before_and_after'];genes=reference['genes'];cells=reference['cells'];(folder/'genes.tsv').write_text('gene_id\n'+'\n'.join(genes)+'\n',encoding='utf8',newline='\n');(folder/'droplets.tsv').write_text('droplet_id\n'+'\n'.join(cells)+'\n',encoding='utf8',newline='\n');(folder/'cells.tsv').write_text('cell_id\n'+'\n'.join(cells)+'\n',encoding='utf8',newline='\n');values=[[5,3,0,1],[0,2,4,0],[2,0,3,5]];(folder/'same.mtx').write_text('%%MatrixMarket matrix coordinate integer general\n3 4 12\n'+''.join(f'{g+1} {c+1} {values[g][c]}\n' for g in range(3) for c in range(4)),encoding='utf8',newline='\n');e=dict(kind='fixed',rho_mode='constant',rho=.1)
        if version=='1.6.2':e['force_accept']=False
        save(folder/'request.json',dict(schema_version=1,mode='AMBIENT',version=version,count_units='raw-integer-counts',matrix_format='matrix-market',clusters='none',counts_relation='raw-subset',raw_counts='same.mtx',filtered_counts='same.mtx',gene_metadata='genes.tsv',droplet_metadata='droplets.tsv',cell_metadata='cells.tsv',soup_source=str(source),soup_range=[0,100],analyses=[dict(id='literal',seed=190731,estimation=e,adjustment=dict(method='subtraction',clustering_scope='cell-only',round_to_integer=False,tolerance=.001,p_cut=.01))],out='result',rscript='C:/Program Files/R/R-4.6.1/bin/Rscript.exe',r_home='C:/Program Files/R/R-4.6.1',r_libraries=list(map(str,libraries)),transport_chunk_entries=2));command=[str(JAVA21/'java.exe'),'-cp',str(jar),'org.jlinalg.cli.SoupXWorkflowCli','--request',str(folder/'request.json')]
